function kthLargest(nums, k) {
  const heap = new MinHeap(); // holds the k largest values seen so far; the smallest of them is on top
  for (const num of nums) {
    heap.push(num);
    if (heap.size() > k) {
      heap.pop(); // throw away the smallest: it can't be in the top k
    }
  }
  return heap.peek(); // the smallest of the top k = the k-th largest
}
